//! `configs/guideline_sources.json`: one entry per researched source (generated by
//! `scripts/make_guideline_registry.py`, then hand-edited: `adapter`, `config`, pacing).
use anyhow::{bail, Context, Result};
use serde::{Deserialize, Serialize};
use serde_json::Value;
use std::path::Path;

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct SourceEntry {
    pub id: String,
    pub name: Option<String>,
    pub group: Option<String>,
    pub scope: Option<String>,
    pub catalog_url: Option<String>,
    /// public | mixed | unknown | needs_auth
    pub access: String,
    pub enabled: bool,
    pub disabled_reason: Option<String>,
    /// Adapter name in `sources::adapter_for` (None = not implemented yet).
    pub adapter: Option<String>,
    #[serde(default = "default_interval")]
    pub min_interval_ms: u64,
    #[serde(default = "default_max")]
    pub max_bytes: u64,
    #[serde(default)]
    pub config: Value,
    #[serde(default)]
    pub notes: Option<String>,
    #[serde(default)]
    pub research: Value,
}

fn default_interval() -> u64 {
    2000
}
fn default_max() -> u64 {
    256 << 20
}

#[derive(Debug, Deserialize)]
struct File {
    sources: Vec<SourceEntry>,
}

pub fn load(path: &Path) -> Result<Vec<SourceEntry>> {
    let f: File = serde_json::from_slice(&std::fs::read(path).with_context(|| format!("read {}", path.display()))?)?;
    Ok(f.sources)
}

pub fn get(path: &Path, id: &str) -> Result<SourceEntry> {
    load(path)?.into_iter().find(|s| s.id == id).with_context(|| format!("unknown source {id}"))
}

/// The only gate between a source and the network. Auth-gated sources are never run (the user provides access
/// later); other disabled sources need an explicit override.
pub fn check_runnable(s: &SourceEntry, allow_disabled: bool) -> Result<()> {
    if s.access == "needs_auth" {
        bail!("{} needs an account/key/entitlement; skipped until the user provides access", s.id);
    }
    if !s.enabled && !allow_disabled {
        bail!("{} is disabled: {}", s.id, s.disabled_reason.as_deref().unwrap_or("no reason given"));
    }
    if s.adapter.is_none() {
        bail!("{} has no adapter yet (set `adapter` in the registry once one exists)", s.id);
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn auth_gated_sources_never_run() {
        let mut s: SourceEntry = serde_json::from_value(serde_json::json!({
            "id": "x", "access": "needs_auth", "enabled": true, "adapter": "static_list"})).unwrap();
        assert!(check_runnable(&s, true).is_err());
        s.access = "public".into();
        assert!(check_runnable(&s, false).is_ok());
        s.enabled = false;
        assert!(check_runnable(&s, false).is_err() && check_runnable(&s, true).is_ok());
    }
}
